#include<stdio.h>
#include<string.h>
int main()
{
    int i,j,k,t,n;
    char a[100][100];
    while(gets(a[0]))
    {
        for(i=0; a[i][0]!='\0'; i++)
        {
            n=strlen(a[i]);
            for(j=0;j<n;j++)
            {
                for(k=0;k<n;k++)
                {
                    if(a[i][j]>a[i][k])
                        break;
                }
                if(k==n)
                    break;
            }
            if(k==n)
                printf("Yes\n");
            else
                printf("No\n");
        }
    }
    return 0;
}

